pageViews.impact=async()=>{
 const{characters}=await api('/api/impact');
 $('#content').innerHTML=head('Patch-Impact-Tracker','Was neue Patches für deine Charaktere bedeuten.')+characters.map(c=>frame(charName(c.character),`${c.outdatedBuild?'<div class="notice"><strong>Gespeicherter Build möglicherweise veraltet.</strong> Prüfe ihn in der Talentwerkstatt.</div>':''}${c.changes.length?`<p>Dein ${esc(c.character.className)} ist möglicherweise von diesen Änderungen betroffen.</p>`+c.changes.map(x=>changeRow(x)+`<small class="muted">Patch ${esc(x.version)} · ${dateText(x.released_on)} · <a href="${esc(x.source_url)}" target="_blank" rel="noopener nofollow">Originalquelle ↗</a></small>`).join(''):'<p class="muted">Keine geprüften Änderungen für diesen Charakter.</p>'}`)).join('')+(characters.length?'':emptyBox('Lege einen Charakter an.'))
};

const DASH={bonus:'Täglicher Bonus',character:'Mein Charakter',raids:'Meine nächsten Raids',gear:'Meine Ausrüstung',professions:'Meine Berufe',guild:'Aktuelles aus der Gilde',stats:'Meine Fortschritte'};
pageViews.dashboard=async()=>{
 const d=await api('/api/dashboard'),cfg=d.user.dashboard,order=[...(cfg.order||[]).filter(k=>DASH[k]),...Object.keys(DASH).filter(k=>!(cfg.order||[]).includes(k))],hidden=new Set(cfg.hidden||[]),main=d.characters.find(c=>c.id===(P.activeChar?.id||d.user.mainCharacterId))||d.characters[0];
 const blocks={
  bonus:()=>`<p>${P.bonusOpen?'Dein Dreh für heute wartet.':'Heute schon gedreht. Morgen wieder!'}</p><button class="${P.bonusOpen?'primary':'subtle'}" onclick="openPage('bonus')">${P.bonusOpen?'Zum Automaten':'Automat ansehen'}</button>`,
  character:()=>main?`<p>${charName(main)}</p><p class="muted">Level ${main.level} · ${esc(main.race)} · ${esc(main.className)}${main.spec?' · '+esc(main.spec):''} · ${esc(d.user.guildRank)}</p>${d.characters.length>1?`<div class="row-actions">${d.characters.map(c=>`<button class="${c.id===main.id?'primary':'subtle'}" onclick="activateCharacter('${esc(c.id)}')">${esc(c.name)}</button>`).join('')}</div>`:''}<button class="link" onclick="openPage('characters')">Charaktere verwalten</button>`:`<button class="primary" onclick="openPage('characters')">Ersten Charakter anlegen</button>`,
  raids:()=>d.raids.map(r=>`<div class="list-row"><button class="link" onclick="openPage('raid','${esc(r.id)}')">${esc(r.name)}</button><small class="muted">${esc(r.instance)} · ${timeText(r.starts_at)} · ${esc(r.character)} · ${ROLE_NAMES[r.role]} · ${SIGNUP_STATUS[r.status]}</small></div>`).join('')||`<p class="muted">Keine Anmeldung.</p><button class="link" onclick="openPage('raids')">Zum Raidplaner</button>`,
  gear:()=>(d.bis.map(b=>`<p>${esc(b.character)} · ${esc(b.spec)}</p>${progressBar(b.done,b.total)}`).join('')||'<p class="muted">Noch keine passende BiS-Liste.</p>')+`<p>${d.wishes} Wunschitems · <button class="link" onclick="openPage('wishlist')">Wunschliste</button></p>`,
  professions:()=>(d.professions.map(p=>`<div class="list-row"><span>${esc(p.profession)} · ${esc(p.name)}</span><strong>${p.skill}</strong></div>`).join('')||'<p class="muted">Keine Berufe eingetragen.</p>')+d.crafts.map(c=>`<div class="list-row"><span>${esc(c.item_name)}</span><span class="pill">${CRAFT_STATUS[c.status]}</span></div>`).join(''),
  guild:()=>`${d.notifications.map(n=>`<div class="list-row"><button class="link" onclick="followLink('${esc(n.link)}','${esc(n.id)}')">${esc(n.message)}</button></div>`).join('')}${d.announcement?`<p>Ankündigung: <button class="link" onclick="openPage('topic','${esc(d.announcement.id)}')">${esc(d.announcement.title)}</button></p>`:''}${d.patch?`<p>Patch: ${esc(d.patch.version)}</p>`:''}${d.unread.map(t=>`<div class="list-row"><button class="link" onclick="openPage('topic','${esc(t.id)}')">Ungelesen: ${esc(t.title)}</button></div>`).join('')}${d.news.map(n=>`<div class="list-row"><a href="${esc(n.link)}" target="_blank" rel="noopener">${esc(n.title)}</a></div>`).join('')}`,
  stats:()=>`<div class="list-row"><span>Raidteilnahmen</span><strong>${d.raidCount}</strong></div><div class="list-row"><span>Dokumentierte Bosskills</span><strong>${d.kills}</strong></div><div class="list-row"><span>Hall-of-Fame-Einträge</span><strong>${d.hall}</strong></div><div class="list-row"><span>Legacy</span><strong>${d.legacy} / ${d.legacyCap}</strong></div>`
 };
 P.dashboard={order,hidden:[...hidden]};
 $('#content').innerHTML=head(`Willkommen, ${esc(d.user.username)}`,'Deine Gildenzentrale.')+`<div class="dash-grid">${order.filter(k=>!hidden.has(k)).map(k=>frame(DASH[k],blocks[k]())).join('')}</div><details class="guild-management"><summary>Dashboard anpassen</summary>${frame('',order.map((k,i)=>`<div class="list-row"><label class="inline-check"><input type="checkbox" ${hidden.has(k)?'':'checked'} onchange="toggleDash('${k}',this.checked)"> ${DASH[k]}</label><span class="row-actions"><button class="subtle" aria-label="Nach oben" ${i?'':'disabled'} onclick="moveDash(${i},-1)">↑</button><button class="subtle" aria-label="Nach unten" ${i<order.length-1?'':'disabled'} onclick="moveDash(${i},1)">↓</button></span></div>`).join(''))}</details>`
};
const saveDash=act(async()=>{await api('/api/me/settings','PUT',{dashboard:P.dashboard});redraw()});
function toggleDash(k,on){P.dashboard.hidden=P.dashboard.hidden.filter(x=>x!==k);if(!on)P.dashboard.hidden.push(k);saveDash()}
function moveDash(i,d){const o=P.dashboard.order;[o[i],o[i+d]]=[o[i+d],o[i]];saveDash()}

/* Class pages: abilities are verified live against the class named in the Wowhead tooltip */
const abilityCache={};
async function classAbilities(id){return abilityCache[id]||=api('/api/abilities/'+id).then(d=>d.abilities).catch(e=>{delete abilityCache[id];throw e})}
const classGuide=id=>`https://www.wowhead.com/forever/guide/classes/${CLASS_INFO[id][2]}/overview`;
let skillSearch='',skillFilter='all';
pageViews.skills=async()=>{
 const cid=plannerClass(),abilities=await classAbilities(cid);
 const shown=abilities.filter(a=>a.name.toLowerCase().includes(skillSearch.toLowerCase())&&(skillFilter==='all'||(skillFilter==='known'?(a.level||1)<=state.level:(a.level||1)>state.level&&(a.level||1)<=state.level+5)));
 $('#content').innerHTML=head('Dein Zauberbuch wächst mit dir.',`${CLASS_INFO[cid][0]} · Stufen und Texte live von Wowhead Forever`,`<span class="pill">${abilities.length} Fähigkeiten</span>`)+`<div class="toolbar"><input aria-label="Fähigkeiten suchen" placeholder="Fähigkeit suchen …" value="${esc(skillSearch)}" onchange="skillSearch=this.value;redraw()"><select aria-label="Fähigkeiten filtern" onchange="skillFilter=this.value;redraw()">${options({all:'Alle Level',known:'Bis zu meinem Level',next:'Die nächsten 5 Level'},skillFilter)}</select><a href="${classGuide(cid)}" target="_blank" rel="noopener">Klassenguide auf Wowhead ↗</a></div><div class="notice">Wichtige Klassenfähigkeiten, keine vollständige Rang- oder Preisliste. Forever-eigene Neuerungen und Talentfähigkeiten können fehlen; Talente findest du in der Talentwerkstatt.</div>`+frame('',shown.map(a=>`<div class="list-row"><span>${spellLink(a)}</span><span class="row-actions"><small class="muted">Stufe ${a.level||1}</small><span class="pill">${(a.level||1)<=state.level?'verfügbar':'später'}</span></span></div>`).join('')||emptyBox('Keine passenden Fähigkeiten.'))
};
pageViews.plan=async()=>{
 const cid=plannerClass(),abilities=await classAbilities(cid).catch(()=>[]),start=Math.max(5,10-(+state.legacy||0)),rows=[{level:start,tag:'Talente',title:'Erster Talentpunkt',text:'Plane deinen Build in der Talentwerkstatt.',page:'talents'},...classMilestones(cid,state.race)];
 const byLevel={};for(const a of abilities)if((a.level||1)>1)(byLevel[a.level]||=[]).push(a.name);
 for(const[level,names]of Object.entries(byLevel))rows.push({level:+level,tag:'Lehrer',title:'Neue Fähigkeiten',text:names.join(', ')});
 for(const d of dungeonCatalog)rows.push({level:d.min,tag:'Dungeon',title:d.name,text:`Planungslevel ${d.min} bis ${d.max} · ${d.zone}`,page:'instances'});
 rows.push({level:60,tag:'Endgame',title:'Raids und Ausrüstung',text:'Raidfortschritt, BiS-Listen und Legacy-Ziele prüfen.',page:'progress'});
 rows.sort((a,b)=>a.level-b.level);
 $('#content').innerHTML=head('Dein Weg von 1 bis 60',`${CLASS_INFO[cid][0]} · aus Live-Daten berechnet`,`<a href="${classGuide(cid)}" target="_blank" rel="noopener">Klassenguide ↗</a>`)+`<div class="notice">${cid===1?'Die Krieger-Meilensteine sind für Forever von Hand gepflegt.':'Klassenquests und Lehrerschritte nach WoW Classic. Forever kann Details ändern, der Klassenguide nennt den aktuellen Stand.'} Neue Fähigkeiten pro Stufe kommen live von Wowhead Forever.</div><div class="card">${rows.map((r,i)=>{const key=`c${cid}-${r.level}-${r.title}`;return `<div class="row ${state.checks[key]?'done':''} ${r.level<state.level?'read':''}"><input type="checkbox" aria-label="${esc(r.title)} erledigt" ${state.checks[key]?'checked':''} onchange="state.checks['${esc(key)}']=this.checked;save()"><div class="num">${r.level}</div><div><span class="tag">${r.tag}</span><br><strong>${esc(r.title)}</strong><p>${esc(r.text)}</p>${r.page?`<button class="link" onclick="openPage('${r.page}')">Öffnen</button>`:''}</div></div>`}).join('')}</div>`
};

/* Daily bonus: the server decides the spin, the reels only show the result */
const REEL_CELLS=26,REEL_HEIGHT=112;
const reelIcon=s=>`<div class="slot-cell q-${esc(s.quality)}"><img src="icons/${esc(s.icon)}.jpg" alt=""><span>${esc(s.name)}</span><b>${s.value}</b></div>`;
function reelStrip(symbols,finalId,cells=REEL_CELLS){const end=symbols.find(s=>s.id===finalId)||symbols[0],list=[];for(let i=0;i<cells-1;i++)list.push(symbols[Math.floor(Math.random()*symbols.length)]);return list.concat(end).map(reelIcon).join('')}
const spinText=r=>r.kind==='triple'?`Drei mal ${r.symbol}! Gold mal 3.`:r.kind==='pair'?`Zwei mal ${r.symbol}! Gold mal 2.`:'Kein Paar, aber Gold gibt es trotzdem.';
const tavernTabs=active=>`<nav class="tavern-tabs" aria-label="Spielunke">${[['bonus','Automat'],['roulette','Roulette'],['blackjack','Blackjack'],['chests','Schatztruhen'],['ranking','Rangliste']].map(([id,label])=>`<button class="${id===active?'selected':''}" onclick="openPage('${id}')">${label}</button>`).join('')}</nav>`;
const QUALITY_NAMES={poor:'Schlecht',common:'Gewöhnlich',uncommon:'Ungewöhnlich',rare:'Selten',epic:'Episch',legendary:'Legendär'};
const rollPips=b=>`<span class="roll-pips" aria-label="${b.rollsLeft} von ${b.rollsPerDay} Drehs übrig">${Array.from({length:b.rollsPerDay},(_,i)=>`<i class="${i<b.rollsLeft?'on':''}"></i>`).join('')}</span> ${b.rollsLeft} von ${b.rollsPerDay} Drehs heute übrig`;
const slotItems=list=>list.map(s=>`<span class="quality-${esc(s.quality)}">${esc(s.name)} ${s.value}</span>`).join(' + ');
pageViews.bonus=async()=>{
 const b=await api('/api/bonus'),idle=['sword','shield','sword'],shown=b.spin?b.spin.reels:idle;
 const locked=!b.rollsLeft&&!b.canRespin;
 $('#content').innerHTML=head('Der Automat',`Drei Drehs pro Tag, um Mitternacht deutscher Zeit gibt es neue. Das Gold zählt auch in der <button class="link" onclick="openPage('chests')">Waffenkammer</button>.`,`<span class="pill">${b.balance} Gildengold</span>`)+tavernTabs('bonus')+`<section class="slot-stage"><div class="slot-machine"><div class="slot-window" aria-live="polite">${shown.map((id,i)=>`<div class="slot-reel" id="reelBox${i}"><div class="slot-strip" id="reel${i}">${reelStrip(b.symbols,id,1)}</div></div>`).join('')}</div><button class="slot-lever" id="slotLever" ${locked?'disabled':''} onclick="spinBonus()" aria-label="${locked?'Heute schon gedreht':'Hebel ziehen'}"><img src="art/sword.svg" alt=""></button></div><p class="slot-rolls" id="slotRolls">${rollPips(b)}</p><p class="slot-result" id="slotResult">${b.spin?`Heute gewonnen: ${b.todayWon} Gildengold. ${b.rollsLeft?`Noch ${b.rollsLeft} ${b.rollsLeft===1?'Dreh':'Drehs'} übrig.`:b.canRespin?'Als Admin drehst du unbegrenzt weiter, das zählt aber nicht.':'Morgen wieder!'}`:'Zieh das Schwert und dreh die Walzen.'}</p><p class="slot-sum" id="slotSum"></p><p class="slot-streak" id="slotStreak">Serie: ${b.streak} ${b.streak===1?'Tag':'Tage'} in Folge · <button class="link" onclick="openPage('ranking')">Zur Rangliste</button> · <button class="link" id="slotMute" onclick="this.textContent=SlotSound.toggle()?'Ton ein':'Ton aus'">${SlotSound.isMuted()?'Ton ein':'Ton aus'}</button></p></section>`+`<div class="two-col">`+frame('Wert der Items',`${[...b.symbols].reverse().map(s=>`<div class="list-row"><span class="slot-pay"><img src="icons/${esc(s.icon)}.jpg" alt=""><span class="quality-${esc(s.quality)}">${esc(s.name)}</span></span><span><small class="muted">${s.jackpotPercent?`Nur als Dreier, ${String(s.jackpotPercent).replace('.',',')} %`:QUALITY_NAMES[s.quality]}</small> &nbsp; <strong>${s.jackpotPercent?`${s.value*9} Gold`:`${s.value} Gold`}</strong></span></div>`).join('')}`)+frame('So zählt der Dreh',`<p>Jedes Item ist seinen Goldwert wert, die drei Walzen werden addiert. Seltene Items erscheinen seltener. Lila und legendäre Items kommen nur als Dreier und füllen alle Walzen.</p><div class="list-row"><span>Zwei gleiche</span><strong>Summe mal 2</strong></div><div class="list-row"><span>Drei gleiche</span><strong>Summe mal 3</strong></div><div class="list-row"><span>Jeder Tag in Folge, beim ersten Dreh</span><strong>+2 Gold, bis 14</strong></div><p class="muted">Gildengold zählt nur hier auf der Seite, es ist weder Spielgold noch Geld.</p>${b.history.length?`<h4>Deine letzten Drehs</h4>${b.history.map(h=>`<div class="list-row read"><span>${dateText(h.day+'T12:00:00Z')}</span><strong>+${h.reward}</strong></div>`).join('')}`:''}`)+`</div>`
};
const spinBonus=act(async()=>{
 const lever=$('#slotLever');if(!lever||lever.disabled)return;lever.disabled=true;lever.classList.add('pulled');SlotSound.lever();
 let r;try{r=await api('/api/bonus/spin','POST',{})}catch(e){lever.disabled=false;lever.classList.remove('pulled');throw e}
 const calm=matchMedia('(prefers-reduced-motion: reduce)').matches,res=r.result,[a,b]=res.items,tease=a.id===b.id,times=calm?[0,0,0]:[1500,2100,tease?4300:2700];
 SlotSound.spin(times[2]);
 $('#slotResult').textContent='Die Walzen drehen ...';$('#slotResult').classList.remove('slot-win');$('#slotSum').textContent='';document.querySelector('.slot-window').classList.remove('jackpot');
 res.items.forEach((item,i)=>{
  const strip=$('#reel'+i),box=$('#reelBox'+i);box.className='slot-reel';strip.innerHTML=reelStrip(r.symbols,item.id);strip.style.transition='none';strip.style.transform='translateY(0)';strip.getBoundingClientRect();strip.style.transition=calm?'none':`transform ${times[i]}ms cubic-bezier(.12,.72,.14,1)`;strip.style.transform=`translateY(-${(REEL_CELLS-1)*REEL_HEIGHT}px)`;
  setTimeout(()=>{box.className=`slot-reel landed q-${item.quality}`;SlotSound.land();if(i===1&&tease&&!calm){box.parentElement.children[2].classList.add('teasing');$('#slotResult').textContent='Zwei gleiche ...';SlotSound.tease()}},times[i])
 });
 await new Promise(done=>setTimeout(done,times[2]+200));
 P.bonusOpen=r.rollsLeft>0;drawNav();if(page!=='bonus')return;$('#slotRolls').innerHTML=rollPips(r);
 $('#reelBox2').classList.remove('teasing');if(res.kind==='triple')document.querySelector('.slot-window').classList.add('jackpot');
 const big=res.items[0].jackpotPercent;SlotSound.coins(big?26:res.kind==='triple'?12:res.kind==='pair'?5:2);if(big){SlotSound.fanfare();showJackpot(res)}
 $('#slotResult').textContent=`${spinText(res)} ${res.free?`${res.reward} Gold, zählt aber nicht.`:`+${res.reward} Gildengold`}`;$('#slotResult').classList.toggle('slot-win',res.kind!=='none');lever.disabled=!r.rollsLeft&&!r.canRespin;$('#slotSum').innerHTML=`${slotItems(res.items)}${res.multiplier>1?` = ${res.sum}, mal ${res.multiplier}`:''}${res.streakBonus?` · Serie +${res.streakBonus}`:''}`;$('#slotStreak').firstChild.textContent=`Serie: ${r.streak} ${r.streak===1?'Tag':'Tage'} in Folge · `;
 document.querySelector('#content .section-head .pill').textContent=`${r.balance} Gildengold`;lever.classList.remove('pulled')
});
function showJackpot(res){
 const item=res.items[0],dialog=document.createElement('dialog');dialog.className=`win-dialog q-${item.quality}`;dialog.setAttribute('aria-labelledby','winTitle');
 dialog.innerHTML=`<div class="win-coins" aria-hidden="true">${Array.from({length:28},(_,i)=>`<i style="left:${Math.random()*100}%;animation-delay:${(i*.09).toFixed(2)}s;animation-duration:${(1.5+Math.random()*1.2).toFixed(2)}s"></i>`).join('')}</div><img class="win-crest" src="art/modcheck-crest.svg" alt=""><p class="win-rarity">${QUALITY_NAMES[item.quality]}!</p><h2 id="winTitle">Glückwunsch, du hast gewonnen!</h2><div class="win-items">${res.items.map(s=>`<img src="icons/${esc(s.icon)}.jpg" alt="">`).join('')}</div><p class="win-name">Drei mal ${esc(item.name)}</p><p class="win-gold">${res.free?`${res.reward} Gold, zählt aber nicht`:`+${res.reward} Gildengold`}</p><button class="primary" onclick="this.closest('dialog').remove()">Einsacken</button>`;
 document.body.append(dialog);dialog.showModal()
}
const RANK_TABS={total:['Kontostand','Gold'],week:['Automat, 7 Tage','Gold'],best:['Bester Dreh','Gold'],roulette:['Roulette-Bilanz','Gold'],blackjack:['Blackjack-Bilanz','Gold'],streak:['Längste Serie','Tage']};
let rankTab='total';
const rankName=p=>p.character?charName(p.character):esc(p.username);
pageViews.ranking=async()=>{
 const{players}=await api('/api/rankings'),[,unit]=RANK_TABS[rankTab],sorted=[...players].sort((a,b)=>b[rankTab]-a[rankTab]||a.username.localeCompare(b.username,'de')),top=sorted.slice(0,3),podium=[top[1],top[0],top[2]].filter(Boolean),mine=sorted.findIndex(p=>p.own);
 $('#content').innerHTML=head('Rangliste','Wer holt am meisten aus dem Automaten?',mine>=0?`<span class="pill">Dein Platz: ${mine+1}</span>`:`<button class="primary" onclick="openPage('bonus')">Jetzt drehen</button>`)+tavernTabs('ranking')+`<div class="rank-tabs" role="group" aria-label="Wertung wählen">${Object.entries(RANK_TABS).map(([k,[label]])=>`<button class="${k===rankTab?'selected':''}" aria-pressed="${k===rankTab}" onclick="rankTab='${k}';redraw()">${label}</button>`).join('')}</div>`+(players.length?`<div class="rank-podium">${podium.map(p=>{const place=sorted.indexOf(p)+1;return `<div class="rank-shield rank-${place} ${p.own?'own':''}"><div class="sw-shield-rim"><div class="sw-shield-face"><b>${place}.</b><span>${esc(p.username)}</span><small>${p[rankTab]} ${unit}</small></div></div></div>`}).join('')}</div>`+sorted.map((p,i)=>`<div class="list-row rank-row ${p.own?'own':''}"><span class="rank-place">${i+1}</span><span class="rank-name">${rankName(p)}<small class="muted">${esc(p.guildRank)}</small></span><span class="rank-stats"><small class="muted">${p.spins} Drehs · Serie ${p.streak}</small><strong>${p[rankTab]} ${unit}</strong></span></div>`).join(''):emptyBox('Noch hat niemand gedreht. Der erste Platz ist frei!'))
};

/* Talent workshop: marks reviewed changes and keeps saved builds visible */
async function loadTalentChanges(){try{const{changes}=await api('/api/patches/talents');window.talentChanges={};for(const c of changes)(window.talentChanges[c.object_id]||=[]).push(c)}catch{window.talentChanges={}}}
(async()=>{await Promise.all([refreshUser().catch(()=>{}),loadTalentChanges()]);applyStartRoute();render()})();
